∀ {P : ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space} {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space} {C : ℝ},
  Breakdown.IsSigmaProfile P W G H C → ∀ (σ : ℝ) (y : Breakdown.Space), W (σ + 1) y = W σ y

∀ {u : ↥Breakdown.Cert.XX} {Y : ℝ → ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {g : Fin 3 → ℝ → Breakdown.Space → Breakdown.Space} {h : Fin 3 → Fin 3 → ℝ → Breakdown.Space → Breakdown.Space}
  {σ : ℝ},
  ¬Breakdown.Cert.Internal.SliceReading.IsGoodTime u Y v g h σ →
    Breakdown.Cert.Internal.SliceReading.goodVel u Y v g h σ = 0

∀ {P R : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation ∅ P v G H g →
    ∀ (N : ℕ),
      MeasureTheory.IntegrableOn (fun z => g z.1 z.2) (Set.Icc (-↑N) ↑N ×ˢ Metric.closedBall 0 R) MeasureTheory.volume

∀ {u : ↥Breakdown.Cert.XX} {Y : ℝ → ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {g : Fin 3 → ℝ → Breakdown.Space → Breakdown.Space} {h : Fin 3 → Fin 3 → ℝ → Breakdown.Space → Breakdown.Space}
  {σ : ℝ},
  Breakdown.Cert.Internal.SliceReading.IsGoodTime u Y v g h σ →
    ∫⁻ (y : Breakdown.Space), ENNReal.ofReal (‖Breakdown.Cert.Internal.SliceFields.gradField (fun j => g j σ) y‖ ^ 2) ≤
      ENNReal.ofReal (‖Breakdown.Cert.gradPart (↑↑u ↑σ)‖ ^ 2)

∀ {P R : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation ∅ P v G H g →
    ∀ (N : ℕ),
      MeasureTheory.IntegrableOn (fun z => (G z.1 z.2) z.2) (Set.Icc (-↑N) ↑N ×ˢ Metric.closedBall 0 R)
        MeasureTheory.volume

∀ {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space} {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation ∅ P v G H g →
    MeasureTheory.AEStronglyMeasurable (fun z => Breakdown.Cert.Internal.TimeModulus.transportRate P v G g z.1 z.2)
      MeasureTheory.volume

∀ {u : ↥Breakdown.Cert.XX} {Y : ℝ → ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {g : Fin 3 → ℝ → Breakdown.Space → Breakdown.Space} {h : Fin 3 → Fin 3 → ℝ → Breakdown.Space → Breakdown.Space}
  {σ : ℝ},
  Breakdown.Cert.Internal.SliceReading.IsGoodTime u Y v g h σ →
    Breakdown.Cert.Internal.SliceReading.goodVel u Y v g h σ = v σ

∀ {P : ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space} {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space} {C : ℝ},
  Breakdown.IsSigmaProfile P W G H C → ¬∀ᵐ (z : ℝ × Breakdown.Space), W z.1 z.2 = 0

∀ {P : ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space} {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space} {C : ℝ},
  Breakdown.IsSigmaProfile P W G H C → MeasureTheory.AEStronglyMeasurable (fun z => H z.1 z.2) MeasureTheory.volume

∀ {a b : WithLp 2 (↥Breakdown.Freq.X × ↥Breakdown.Freq.X)},
  a ∈ {q | Breakdown.Freq.IsHalfSspOf q.fst q.snd} →
    b ∈ {q | Breakdown.Freq.IsHalfSspOf q.fst q.snd} → a + b ∈ {q | Breakdown.Freq.IsHalfSspOf q.fst q.snd}

∀ {P R : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation ∅ P v G H g →
    (Breakdown.periodBallLIntegral R fun σ y => ‖v σ y‖ ^ 2) < ⊤ →
      ∀ (δ : ℝ) (N : ℕ),
        MeasureTheory.IntegrableOn (Breakdown.Cert.Internal.TimeModulus.transportDefect P δ v G g)
          (Set.Icc (-↑N) ↑N ×ˢ Metric.closedBall 0 R) MeasureTheory.volume

∀ {ι : Type u_1} {M : Type u_3} {N : Type u_4} [inst : AddCommMonoid M] [inst_1 : AddCommMonoid N] {G : Type u_7}
  [inst_2 : FunLike G M N] [AddMonoidHomClass G M N] (g : G) (f : ι → M) (s : Finset ι),
  ∑ x ∈ s, g (f x) = g (∑ x ∈ s, f x)

∀ {ι : Type u_1} {M : Type u_3} {N : Type u_4} [inst : AddCommMonoid M] [inst_1 : AddCommMonoid N] {G : Type u_7}
  [inst_2 : FunLike G M N] [AddMonoidHomClass G M N] (g : G) (f : ι → M) (s : Finset ι),
  ∑ x ∈ s, g (f x) = g (∑ x ∈ s, f x)

∀ {P : ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space} {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space} {C : ℝ},
