∀ {α : Type u_1} {E : Type u_2} {E' : Type u_3} [inst : MeasurableSpace α] {μ : MeasureTheory.Measure α}
  [inst_1 : NormedAddCommGroup E] [InnerProductSpace ℝ E] [inst_3 : NormedAddCommGroup E'] [InnerProductSpace ℝ E']
  (F : ↥(MeasureTheory.Lp E 2 μ)) (G : ↥(MeasureTheory.Lp E' 2 μ)), ∫ (t : α), ‖↑↑F t‖ * ‖↑↑G t‖ ∂μ ≤ ‖F‖ * ‖G‖

∀ {P R : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation ∅ P v G H g →
    (Breakdown.periodBallLIntegral R fun σ y => ‖v σ y‖ ^ 2) < ⊤ →
      ∀ (N : ℕ),
        MeasureTheory.IntegrableOn (fun z => Breakdown.Cert.Internal.TimeModulus.transportRate P v G g z.1 z.2)
          (Set.Icc (-↑N) ↑N ×ˢ Metric.closedBall 0 R) MeasureTheory.volume

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : InnerProductSpace ℝ E] {R K : ℝ}
  {ρ : E → ℝ → Breakdown.Space → Breakdown.Space} (h : Breakdown.Cert.Internal.HeldLimitReadings.IsLocalFamily R K ρ)
  (u : E), ‖h.lin u‖ ≤ √K * ‖u‖

∀ (η : ℝ) (hη : 0 < η),
  Breakdown.Cert.Internal.TranslationCriterion.bumpOfRadius η hη =
    { rIn := η / 2, rOut := η, rIn_pos := ⋯, rIn_lt_rOut := ⋯ }

∀ {P : ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space} {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
