∀ {α : Type u_1} {E : Type u_2} {F : Type u_3} [inst : MeasurableSpace α] {μ : MeasureTheory.Measure α}
  [inst_1 : NormedAddCommGroup E] [inst_2 : NormedAddCommGroup F] (a : ↥(MeasureTheory.Lp E 2 μ))
  (b : ↥(MeasureTheory.Lp F 2 μ)), (∀ᵐ (t : α) ∂μ, ‖↑↑a t‖ = ‖↑↑b t‖) → ‖a‖ = ‖b‖

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : InnerProductSpace ℝ E] {R K : ℝ}
