  (u : E), ‖MeasureTheory.MemLp.toLp (fun z => ρ u z.1 z.2) ⋯‖ ≤ √K * ‖u‖

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : InnerProductSpace ℝ E] {R K : ℝ}
  {ρ : E → ℝ → Breakdown.Space → Breakdown.Space} (h : Breakdown.Cert.Internal.HeldLimitReadings.IsLocalFamily R K ρ)
  (u : E), h.clm u = MeasureTheory.MemLp.toLp (fun z => ρ u z.1 z.2) ⋯

∀ {α : Type u_1} {β : Type u_2} {F : Type u_3} [inst : MeasurableSpace α] [inst_1 : MeasurableSpace β]
  [inst_2 : NormedAddCommGroup F] {p : ENNReal} {ν : MeasureTheory.Measure β}
  (g : MeasureTheory.SimpleFunc α ↥(MeasureTheory.Lp F p ν)), MeasureTheory.StronglyMeasurable fun z => ↑↑(g z.1) z.2

∀ {u : ↥Breakdown.Cert.XX} {Y : ℝ → ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
